(function (){'use strict';function convertArabicNumerals(str){if (!str)return '';return String(str).replace(/[٠-٩]/g,function (d){return String.fromCharCode(d.charCodeAt(0)-1632+48);}).replace(/[۰-۹]/g,function (d){return String.fromCharCode(d.charCodeAt(0)-1776+48);});}function getCookie(name){var cookieValue=null;if (document.cookie&&document.cookie!==''){var cookies=document.cookie.split(';');for (var i=0;i<cookies.length;i++){var cookie=cookies[i].trim();if (cookie.substring(0,name.length+1)===(name+'=')){cookieValue=decodeURIComponent(cookie.substring(name.length+1));break;}}}return cookieValue;}function getErrorSlot(field,create){if (!field)return null;var anchor=field.closest('.intl-phone-wrapper')||field;var slot=anchor.nextElementSibling;if (slot&&slot.classList&&slot.classList.contains('form-error')){return slot;}if (!create)return null;slot=document.createElement('p');slot.className='form-error';slot.setAttribute('role','alert');slot.dataset.autoError='true';slot.style.display='none';anchor.insertAdjacentElement('afterend',slot);return slot;}function showFieldError(field,message){if (!field)return;field.classList.add('is-invalid');field.classList.add('reg-input--invalid');var wizardError=document.getElementById(field.id+'_error');if (wizardError){wizardError.textContent=message;wizardError.style.display='block';return;}var slot=getErrorSlot(field,true);if (slot){slot.textContent=message;slot.style.display='block';}}function clearFieldError(field){if (!field)return;field.classList.remove('is-invalid');field.classList.remove('reg-input--invalid');var wizardError=document.getElementById(field.id+'_error');if (wizardError){wizardError.textContent='';wizardError.style.display='none';}var slot=getErrorSlot(field,false);if (slot){slot.textContent='';slot.style.display='none';}}function clearAllErrors(form){if (!form)return;form.querySelectorAll('.is-invalid,.reg-input--invalid').forEach(function (el){el.classList.remove('is-invalid');el.classList.remove('reg-input--invalid');});form.querySelectorAll('.form-error,.reg-field-error').forEach(function (el){el.textContent='';el.style.display='none';});var banner=form.querySelector('.lead-form-alert');if (banner){banner.remove();}}function showFormAlert(form,message,type){if (!form)return;var existing=form.querySelector('.lead-form-alert');if (existing)existing.remove();var alert=document.createElement('div');alert.className='lead-form-alert alert alert--'+(type||'error');alert.setAttribute('role','alert');alert.style.margin='0 0 1rem 0';alert.style.padding='0.75rem 1rem';alert.style.borderRadius='var (--radius-sm,6px)';alert.style.fontSize='0.875rem';alert.textContent=message;form.insertBefore(alert,form.firstChild);if (typeof alert.scrollIntoView==='function'){alert.scrollIntoView({behavior:'smooth',block:'nearest'});}}function unlockLeadForm(form){if (!form)return;form.removeAttribute('data-submitting');if (typeof window.unlockForm==='function'){window.unlockForm(form);}else{var submitBtns=form.querySelectorAll('button[type="submit"],input[type="submit"]');submitBtns.forEach(function (btn){btn.disabled=false;btn.style.pointerEvents='';btn.style.opacity='';btn.style.cursor='';btn.classList.remove('is-loading');var originalText=btn.getAttribute('data-original-text');if (originalText){btn.innerHTML=originalText;}});}}function lockLeadForm(form){if (!form)return;form.dataset.submitting='true';var submitBtns=form.querySelectorAll('button[type="submit"],input[type="submit"]');submitBtns.forEach(function (btn){if (!btn.hasAttribute('data-original-text')){btn.setAttribute('data-original-text',btn.innerHTML||btn.value);}btn.style.pointerEvents='none';btn.style.opacity='0.7';btn.style.cursor='wait';btn.classList.add('is-loading');btn.innerHTML='<span style="opacity:0.85">⏳ جاري الإرسال...</span>';});}function setupFormInputs(form){var phoneInputs=form.querySelectorAll('input[type="tel"],input[name="phone_number"],input[name="phone"]');phoneInputs.forEach(function (input){input.addEventListener('input',function (){var converted=convertArabicNumerals(this.value);if (this.value!==converted){this.value=converted;}clearFieldError(this);});});var allInputs=form.querySelectorAll('input,select,textarea');allInputs.forEach(function (input){input.addEventListener('input',function (){clearFieldError(this);});input.addEventListener('change',function (){clearFieldError(this);});});}function ensureCombinedPhone(form){var phoneInput=form.querySelector('input[name="phone_number"]');var hiddenCode=form.querySelector('input[name="country_code"]');var combinedPhone=form.querySelector('input[name="phone"]');if (phoneInput&&combinedPhone){var rawVal=convertArabicNumerals(phoneInput.value).trim();var cleanDigits=rawVal.replace(/\D/g,'').replace(/^0+/,'');var codeVal=hiddenCode?hiddenCode.value.trim():'+60';if (cleanDigits){combinedPhone.value=codeVal+cleanDigits;}else{combinedPhone.value='';}}}function handleLeadFormSubmit(form,e,isRetry){e.preventDefault();e.stopPropagation();if (form.dataset.submitting==='true'&&!isRetry){return false;}if (typeof window.syncAllFormsCsrf==='function'){window.syncAllFormsCsrf();}ensureCombinedPhone(form);if (form.id==='regWizardForm'){if (typeof window.validateRegistrationStep1==='function'&&!window.validateRegistrationStep1()){var alpineContainer=form.closest('[x-data]');if (alpineContainer&&alpineContainer.__x&&alpineContainer.__x.$data){alpineContainer.__x.$data.regStep=1;}unlockLeadForm(form);return false;}if (typeof window.validateRegistrationStep2==='function'&&!window.validateRegistrationStep2()){var alpineCont=form.closest('[x-data]');if (alpineCont&&alpineCont.__x&&alpineCont.__x.$data){alpineCont.__x.$data.regStep=2;}unlockLeadForm(form);return false;}}else{var isValid=true;var firstInvalid=null;var requiredInputs=form.querySelectorAll('[required]');requiredInputs.forEach(function (field){if (!field.value||!field.value.trim()){isValid=false;if (!firstInvalid)firstInvalid=field;showFieldError(field,'هذا الحقل مطلوب.');}});if (!isValid){if (firstInvalid&&typeof firstInvalid.focus==='function'){if (typeof firstInvalid.scrollIntoView==='function'){firstInvalid.scrollIntoView({behavior:'smooth',block:'center'});}firstInvalid.focus();}unlockLeadForm(form);return false;}}lockLeadForm(form);var watchdog=setTimeout(function (){if (document.body.contains(form)&&form.dataset.submitting==='true'){unlockLeadForm(form);showFormAlert(form,'استغرقت عملية الإرسال وقتاً أطول من المعتاد. يرجى التحقق من اتصالك بالإنترنت وإعادة المحاولة.','error');}},12000);var formData=new FormData(form);var csrfToken=getCookie('csrftoken')||(form.querySelector('input[name="csrfmiddlewaretoken"]')?form.querySelector('input[name="csrfmiddlewaretoken"]').value:'');var submitUrl=form.getAttribute('action')||'/leads/submit/';fetch(submitUrl,{method:'POST',body:formData,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json','X-CSRFToken':csrfToken},credentials:'same-origin'}).then(function (response){clearTimeout(watchdog);return response.json().then(function (data){return{status:response.status,ok:response.ok,data:data};}).catch(function (){return{status:response.status,ok:response.ok,data:null};});}).then(function (result){var status=result.status;var data=result.data;if (result.ok&&data&&data.success){var redirectUrl=data.redirect_url||'/leads/thank-you/';try{var formKey='sg_lead_draft_'+window.location.pathname.split('/').join('_');localStorage.removeItem(formKey);}catch(e){}window.location.href=redirectUrl;return;}if (status===403&&!isRetry){if (typeof window.syncAllFormsCsrf==='function'){window.syncAllFormsCsrf();}setTimeout(function (){handleLeadFormSubmit(form,e,true);},300);return;}if (status===429||(data&&data.rate_limit)){unlockLeadForm(form);var rateMsg=(data&&data.message)?data.message:'تم تجاوز الحد المسموح به من الطلبات خلال الساعة الأخيرة لحماية الخدمة.';showFormAlert(form,rateMsg,'error');return;}if (status===400&&data&&data.errors){unlockLeadForm(form);var firstInvalidField=null;var errorKeys=Object.keys(data.errors);errorKeys.forEach(function (fieldKey){var errArr=data.errors[fieldKey];var errMsg=(errArr&&errArr.length&&errArr[0].message)?errArr[0].message:'يرجى تصحيح هذا الحقل.';var inputEl=form.querySelector('[name="'+fieldKey+'"]');if (fieldKey==='phone'){inputEl=form.querySelector('[name="phone_number"]')||inputEl;}if (inputEl){showFieldError(inputEl,errMsg);if (!firstInvalidField)firstInvalidField=inputEl;}});var generalMsg=data.message||'حدث خطأ في النموذج. يرجى التحقق من البيانات المدخلة.';showFormAlert(form,generalMsg,'error');if (firstInvalidField){if (form.id==='regWizardForm'){var isStep1Field=['name','email','phone','phone_number','nationality','custom_nationality'].indexOf(firstInvalidField.name)!==-1;var alpineModal=form.closest('[x-data]');if (alpineModal&&alpineModal.__x&&alpineModal.__x.$data){alpineModal.__x.$data.regStep=isStep1Field?1:2;}}if (typeof firstInvalidField.scrollIntoView==='function'){firstInvalidField.scrollIntoView({behavior:'smooth',block:'center'});}firstInvalidField.focus();}return;}unlockLeadForm(form);var errMessage=(data&&data.message)?data.message:'حدث خطأ غير متوقع أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';showFormAlert(form,errMessage,'error');}).catch(function (error){clearTimeout(watchdog);unlockLeadForm(form);showFormAlert(form,'تعذر الاتصال بالخادم. يرجى التحقق من اتصال الإنترنت والمحاولة مرة أخرى.','error');});}function initLeadForms(){var leadForms=document.querySelectorAll('form[data-lead-form],form[action*="/leads/submit"],form[action*="leads:submit"],form[id="regWizardForm"]');leadForms.forEach(function (form){if (form.dataset.leadFormInit==='true')return;form.dataset.leadFormInit='true';setupFormInputs(form);form.addEventListener('submit',function (e){handleLeadFormSubmit(form,e,false);});});}if (document.readyState==='loading'){document.addEventListener('DOMContentLoaded',initLeadForms);}else{initLeadForms();}window.initLeadForms=initLeadForms;})();